from torchvision import datasets, transforms
from torch.utils.data import DataLoader, random_split
import torch

# Load CIFAR-10 dataset
train_dataset = datasets.CIFAR10(root='./data', train=True, download=True, transform=transforms.ToTensor())
test_dataset = datasets.CIFAR10(root='./data', train=False, download=True, transform=transforms.ToTensor())

# Use only a small subset of the training and test data
train_subset = torch.utils.data.Subset(train_dataset, range(500))
test_subset = torch.utils.data.Subset(test_dataset, range(100))

# Split training data into original and rotated versions
train_loader_original, train_loader_rotated = random_split(train_subset, [len(train_subset) * 3 // 4, len(train_subset) * 1 // 4])

# Function to rotate images
def rotate_images(image, angle):
    if angle == 0:
        return image
    elif angle == 90:
        return torch.rot90(image, 1, [2, 3])
    elif angle == 180:
        return torch.rot90(image, 2, [2, 3])
    elif angle == 270:
        return torch.rot90(image, 3, [2, 3])
    else:
        raise ValueError("Angle must be 0, 90, 180, or 270 degrees.")

# Apply rotation to the rotated training data
rotated_train_dataset = []
for img, label in train_loader_rotated:
    for angle in [0, 90, 180, 270]:
        rotated_img = rotate_images(img, angle)
        rotated_train_dataset.append((rotated_img, label))

# Convert to a DataLoader for the rotated training data
rotated_train_loader = DataLoader(rotated_train_dataset, batch_size=32, shuffle=True)
